# f3resync_src.f -- DECLARED compile file list for the f3_resync gate (G1).
#   gate bat : sim\f3_resync\run_tb_f3_resync.bat   (registered 2026-10-15, #20)
#   config   : xsim only; the 5 arms (F/L/M1/M2/CTRL) share ONE compile list --
#              only the DUT source is per-arm, and the three variants are
#              mutually exclusive (each appears exactly once as a literal in the
#              bat):  F / L / CTRL -> rtl/vlan_strip.v ;  M1 -> mut_m1.v ;
#              M2 -> mut_m2.v.  Mutants are (re)generated by
#              sim/f3_resync/mut/mk_mut_f3.py (in FINGERPRINT_GLOBS via paths.txt).
#   Entries are repo-relative; sim/p4gates/p4gate.py manifestcheck asserts this
#   list == the list literally present in the gate .bat.
rtl/crc32_8b.v
rtl/fifo_sync.v
rtl/fifo_async.v
rtl/mac_rx_64.v
rtl/vlan_strip.v
sim/f3_resync/mut/mut_m1.v
sim/f3_resync/mut/mut_m2.v
sim/f3_resync/tb_f3_resync.v
